import React, { Component } from "react";
import "./Header.css";
import HelpAnimalModal from "../HelpAnimalModal";

export default class Header extends Component {
  constructor(props) {
    super(props);
    this.state = {
      header1data: [],
      header2data: [],
      showHelpAnimalModal: false,
    };
  }

  componentDidMount() {
    this.fetchHeader1Menu();
    this.fetchHeader2Menu();
  }

  fetchHeader1Menu = () => {
    fetch(`http://localhost:3001/menupagesquary/1`, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json'
      },
      body: JSON.stringify({})
    })
      .then(response => response.json())
      .then(data => {
        this.setState({ header1data: data });
      })
      .catch(error => console.error('Error fetching data:', error));
  }

  fetchHeader2Menu = () => {
    fetch(`http://localhost:3001/menupagesquary/2`, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json'
      },
      body: JSON.stringify({})
    })
      .then(response => response.json())
      .then(data => {
        this.setState({ header2data: data });
      })
      .catch(error => console.error('Error fetching data:', error));
  }

  toggleHelpAnimalModal = () => {
    this.setState({ showHelpAnimalModal: !this.state.showHelpAnimalModal });
  }

  handleMenuClick = (menuItemText) => {
    const { onMenuClick } = this.props;
    onMenuClick(menuItemText);
  }

  render() {
    const { header1data, header2data, showHelpAnimalModal } = this.state;

    const logoText = header1data.length > 0 ? header1data[0].text : "Loading...";

    return (
      <div>
        <nav>
          <ul>
            <li><h1 className="logo"><a href="/Homepage">{logoText}</a></h1></li>
          </ul>
          <ul>
            {header1data.filter(menuItem => menuItem.menuId === 1).map(headerMenu => (
              <li key={headerMenu.itemId}>
                <a className={headerMenu.itemstyle} href={headerMenu.itemurl}>{headerMenu.itemtext}</a>
              </li>
            ))}
          </ul>
        </nav>

        <div className="orange-navbar">
          <div className="navcontainer">
            {header2data.filter(menuItem => menuItem.menuId === 2).map(headerMenu => (
              <li key={headerMenu.itemId}>
                <a
                  className={headerMenu.itemstyle}
                  href={headerMenu.itemurl}
                  onClick={() => this.handleMenuClick(headerMenu.itemtext)}
                >
                  {headerMenu.itemtext}
                </a>
              </li>
            ))}
          </div>
        </div>

        <HelpAnimalModal show={showHelpAnimalModal} onClose={this.toggleHelpAnimalModal} />
      </div>
    );
  }
}
